INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_electrical_bb21ba1641', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_electrical_bb21ba1641","link":null},"plain_text":"standard_electrical_bb21ba1641","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"electrical"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"RCD trip-time and trip-current verification (renovation detailstime)","link":null},"plain_text":"RCD trip-time and trip-current verification (renovation detailstime)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Each wet-area RCD trips within ≤0.1 s at rated leakage current (typically 30 mA); test repeated 3 times with consistent result; trip-current measured within ±10% of rated value.","link":null},"plain_text":"Each wet-area RCD trips within ≤0.1 s at rated leakage current (typically 30 mA); test repeated 3 times with consistent result; trip-current measured within ±10% of rated value.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"test_report"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50303-2015"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2015/art_17339_223437.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"RCD trip-time >0.2 s under measurement"},{"name":"RCD test button works but actual leakage does not trip"},{"name":"wrong-rated RCD installed at bathroom branch"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: instrum