INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_air_quality_4bf9b69ba6', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_air_quality_4bf9b69ba6","link":null},"plain_text":"standard_air_quality_4bf9b69ba6","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Post-handover formaldehyde retest at month 3 and month 6 (renovation detailsreinspection)","link":null},"plain_text":"Post-handover formaldehyde retest at month 3 and month 6 (renovation detailsreinspection)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Repeat GB 50325 Class I sampling at month 3 and month 6 post-handover; formaldehyde ≤ 0.07 mg/m³ each retest; TVOC ≤ 0.45 mg/m³; if either retest fails, isolate the high-emission source (typicallyrenovation details furniture / textiles) and re-treat.","link":null},"plain_text":"Repeat GB 50325 Class I sampling at month 3 and month 6 post-handover; formaldehyde ≤ 0.07 mg/m³ each retest; TVOC ≤ 0.45 mg/m³; if either retest fails, isolate the high-emission source (typicallyrenovation details furniture / textiles) and re-treat.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"formaldehyde rebound to 0.12 mg/m³ at month 3 after new wardrobe delivery"},{"name":"single pre-move-in test under-detected slow-release peak"},{"name":"retest skipped — owner discovered exceedance via independent testing"}]},"evidence_register":{"type":"select","select":{"name":"project_calendar"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Follow-up cadence: month-3 and month-6 third-party air retests; record results and trigger source-isolation workflow on any exceedance.","link":null},"plain_text":"Follow-up cadence: month-3 and month-6 third-party air retests; record results and trigger source-isolation workflow on any exceedance.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_air_quality_34348aa27b', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_air_quality_34348aa27b","link":null},"plain_text":"standard_air_quality_34348aa27b","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Indoor air report integrity — per-pollutant breakdown (renovation details)","link":null},"plain_text":"Indoor air report integrity — per-pollutant breakdown (renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Third-party report shall list each of the 7 GB 50325-2020 pollutants separately (radon, formaldehyde, benzene, toluene, xylene, ammonia, TVOC) with sampling location, instrument model, and calibration date; reports that show only a ''composite'' TVOC pass are rejected.","link":null},"plain_text":"Third-party report shall list each of the 7 GB 50325-2020 pollutants separately (radon, formaldehyde, benzene, toluene, xylene, ammonia, TVOC) with sampling location, instrument model, and calibration date; reports that show only a ''composite'' TVOC pass are rejected.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"report aggregates benzene/toluene/xylene under ''TVOC'' line — masksrenovation details exceedance"},{"name":"no instrument calibration date"},{"name":"sampling location not specified per room"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Do not accept any indoor-air report that aggregates pollutants or omits per-room sampling location; block final handover until a compliant report is filed.","link":null},"plain_text":"Do not accept any indoor-air report that aggregates pollutants or omits per-room sampling location; block final handover until a compliant report is filed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_gas_68702a3ef2', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_gas_68702a3ef2","link":null},"plain_text":"standard_gas_68702a3ef2","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"gas"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Gas-pipe alteration recommissioning by gas-company technician (renovation detailsreinspection)","link":null},"plain_text":"Gas-pipe alteration recommissioning by gas-company technician (renovation detailsreinspection)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Any modification of gas piping, including length extension, fitting replacement, or appliance hookup, completed by gas-company-licensed technician; gas-company recommissioning test (pressure-hold + soap-bubble leak check) passed with written certificate; renovation contractor may not self-certify gas work.","link":null},"plain_text":"Any modification of gas piping, including length extension, fitting replacement, or appliance hookup, completed by gas-company-licensed technician; gas-company recommissioning test (pressure-hold + soap-bubble leak check) passed with written certificate; renovation contractor may not self-certify gas work.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"CJJ 12-2013"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2013/art_17339_216051.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"renovation crew altered gas pipe without gas-company involvement"},{"name":"no leak-test certificate after stove install"},{"name":"gas detector alarm triggered after move-in"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold stove / water-heater use and final handover until a gas-company recommissioning certificate is filed.","link":null},"plain_text":"Hold stove / water-heater use and final handover until a gas-company recommissioning certificate is filed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
