INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_pre_demolition_327f8e5f1c', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_pre_demolition_327f8e5f1c","link":null},"plain_text":"standard_pre_demolition_327f8e5f1c","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"pre_demolition"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Downstairs and adjacent-unit ceiling baseline (renovation details)","link":null},"plain_text":"Downstairs and adjacent-unit ceiling baseline (renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before demolition, the contractor walks the downstairs unit and the two adjacent units (left/right) with their owners'' permission; current ceiling condition documented with dated photos (existing cracks, stains, fixture positions) to establish a baseline for later renovation-damage claims.","link":null},"plain_text":"Before demolition, the contractor walks the downstairs unit and the two adjacent units (left/right) with their owners'' permission; current ceiling condition documented with dated photos (existing cracks, stains, fixture positions) to establish a baseline for later renovation-damage claims.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"neighbor_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"waterproofing"},{"name":"electrical"},{"name":"plumbing"},{"name":"tile"}]},"source_authority":{"type":"select","select":{"name":"Shanghai_2024"}},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"downstairs neighbor claimed pre-existing crack as renovation damage"},{"name":"no baseline photo — dispute went to mediation"},{"name":"adjacent units not walked — later noise/vibration complaint had no rebuttal"}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold demolition start until baseline photos with downstairs+adjacent owners'' written acknowledgement are filed.","link":null},"plain_text":"Hold demolition start until baseline photos with downstairs+adjacent owners'' written acknowledgement are filed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_rough_in_a87db50b0a', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_rough_in_a87db50b0a","link":null},"plain_text":"standard_rough_in_a87db50b0a","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"rough_in"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Third-party renovation details mid-construction inspection (concealed workrenovation details)","link":null},"plain_text":"Third-party renovation details mid-construction inspection (concealed workrenovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Engage an independent renovation details (licensed inspector) for a mid-construction visit after waterproofing + electrical + plumbing rough-in but before tile and ceiling closure; written report identifies any code deviations and is referenced in the change-order log.","link":null},"plain_text":"Engage an independent renovation details (licensed inspector) for a mid-construction visit after waterproofing + electrical + plumbing rough-in but before tile and ceiling closure; written report identifies any code deviations and is referenced in the change-order log.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2024"}},"source_url":{"type":"url","url":"https://www.cida.org.cn/"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"concealed joint discovered post-tile — rework cost 5× pre-tile"},{"name":"no third-party visit — owner relied solely on contractor self-cert"},{"name":"verbal verbal-only finding not recorded"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold tile scheduling until a written third-party renovation details report on concealed-works is filed and any findings have a remediation row.","link":null},"plain_text":"Hold tile scheduling until a written third-party renovation details report on concealed-works is filed and any findings have a remediation row.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_final_handover_b0a9f8eddd', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_final_handover_b0a9f8eddd","link":null},"plain_text":"standard_final_handover_b0a9f8eddd","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"final_handover"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Owner-walkthrough video record (renovation details)","link":null},"plain_text":"Owner-walkthrough video record (renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Final walkthrough is video-recorded room-by-room with timestamp + room callout; punch-list items spoken aloud at the moment of identification; owner and contractor both visible in the recording at start and at handover signoff; recording retained for warranty period.","link":null},"plain_text":"Final walkthrough is video-recorded room-by-room with timestamp + room callout; punch-list items spoken aloud at the moment of identification; owner and contractor both visible in the recording at start and at handover signoff; recording retained for warranty period.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"video"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2024"}},"source_url":{"type":"url","url":"https://www.sccc315.com/"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"punch-list item later disputed by contractor as post-handover damage"},{"name":"no video — owner-signoff alleged coerced"},{"name":"walkthrough recorded but no timestamp / room callout"}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: complete walkthrough video is filed alongside the signed punch list and warranty register before final-payment release.","link":null},"plain_text":"Required record: complete walkthrough video is filed alongside the signed punch list and warranty register before final-payment release.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_post_handover_warranty_8fedb8434b', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_post_handover_warranty_8fedb8434b","link":null},"plain_text":"standard_post_handover_warranty_8fedb8434b","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"post_handover_warranty"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai municipal complaint-channel notice at handover (Shanghairenovation detailsrenovationrenovation details)","link":null},"plain_text":"Shanghai municipal complaint-channel notice at handover (Shanghairenovation detailsrenovationrenovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At handover, the contractor provides written notice of consumer-complaint channels (Shanghai 12315 platform, Shanghairenovation details sccc315.com, renovation detailsproperty managementrenovation details 962121); owner signs that channels have been disclosed and remain in effect through the warranty period.","link":null},"plain_text":"At handover, the contractor provides written notice of consumer-complaint channels (Shanghai 12315 platform, Shanghairenovation details sccc315.com, renovation detailsproperty managementrenovation details 962121); owner signs that channels have been disclosed and remain in effect through the warranty period.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"Shanghai_2024"}},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"owner unaware of 12315 escalation path"},{"name":"complaint hotline not disclosed at handover"},{"name":"contractor obstructed complaint escalation by withholding signed contract copy"}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: signed channel-disclosure sheet is in the handover packet before final-payment release.; source clause must be confirmed against the cited document before contract use. 962121 hotline number latest 2024 routing.","link":null},"plain_text":"Required record: signed channel-disclosure sheet is in the handover packet before final-payment release.; source clause must be confirmed against the cited document before contract use. 962121 hotline number latest 2024 routing.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_contract_a26b43c45f', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_contract_a26b43c45f","link":null},"plain_text":"standard_contract_a26b43c45f","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Vendor financial-health verification before signing main contract (renovationrenovation details/renovation details)","link":null},"plain_text":"Vendor financial-health verification before signing main contract (renovationrenovation details/renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before signing, the owner verifies the vendor''s public business records: (a) renovation details renovation details in active status; (b) no renovation details / renovation details listing against the legal representative; (c) no abnormal-operations or major dissolution filing in the prior 12 months; (d) no concentrated renovation details cluster (>30 unresolved in trailing 6 months) for renovation details / renovation details / renovation details keywords; (e) registered capital paid-in covers at least 12 months of the project deposit; results captured in a one-page risk memo signed by owner.","link":null},"plain_text":"Before signing, the owner verifies the vendor''s public business records: (a) renovation details renovation details in active status; (b) no renovation details / renovation details listing against the legal representative; (c) no abnormal-operations or major dissolution filing in the prior 12 months; (d) no concentrated renovation details cluster (>30 unresolved in trailing 6 months) for renovation details / renovation details / renovation details keywords; (e) registered capital paid-in covers at least 12 months of the project deposit; results captured in a one-page risk memo signed by owner.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"tile"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2025"}},"source_url":{"type":"url","url":"https://www.gsxt.gov.cn/"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"large renovation details platform collapsed mid-project with 800+ unfinished sites — owner had paid 60% deposit"},{"name":"regional renovation details vendor with 68 affected households and ¥1.6M+ deposits lost — no pre-sign credit check"},{"name":"vendor legal representative on renovation details list — owner not aware until after contract signed"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold main-contract signing and any deposit transfer until the risk memo is signed; re-run the check every 60 days for projects with phased payment schedules.","link":null},"plain_text":"Hold main-contract signing and any deposit transfer until the risk memo is signed; re-run the check every 60 days for projects with phased payment schedules.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_contract_84f8277d42', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_contract_84f8277d42","link":null},"plain_text":"standard_contract_84f8277d42","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Third-party fund-escrow account with phase-release gates (renovationrenovation details)","link":null},"plain_text":"Third-party fund-escrow account with phase-release gates (renovationrenovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"All payments above ¥10,000 routed through a third-party bank-escrow account (e.g., platform renovation detailsrenovationrenovation details model) rather than direct transfer to the vendor; release schedule tied to written acceptance gates: 30% after demolition+rough-in acceptance, 30% after waterproofing+concealed-works acceptance, 25% after tile+cabinet acceptance, 10% after final-handover acceptance, 5% retained for 6-month warranty; release at each gate requires owner signature, not vendor self-certification.","link":null},"plain_text":"All payments above ¥10,000 routed through a third-party bank-escrow account (e.g., platform renovation detailsrenovationrenovation details model) rather than direct transfer to the vendor; release schedule tied to written acceptance gates: 30% after demolition+rough-in acceptance, 30% after waterproofing+concealed-works acceptance, 25% after tile+cabinet acceptance, 10% after final-handover acceptance, 5% retained for 6-month warranty; release at each gate requires owner signature, not vendor self-certification.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"waterproofing"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"consumer_protection_2025"}},"source_url":{"type":"url","url":"https://www.thepaper.cn/newsDetail_forward_30379632"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"owner paid 70% lump-sum up front — vendor ''disappeared'' before tile work"},{"name":"platform escrow released funds on vendor''s signature without owner approval"},{"name":"no 5% warranty retention — vendor unreachable for 6-month defects"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold deposit transfer to vendor''s own account; verify escrow contract is signed before demolition; lock each release gate behind a passing acceptance record.","link":null},"plain_text":"Hold deposit transfer to vendor''s own account; verify escrow contract is signed before demolition; lock each release gate behind a passing acceptance record.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_rough_in_c152e8eb7e', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_rough_in_c152e8eb7e","link":null},"plain_text":"standard_rough_in_c152e8eb7e","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"rough_in"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-1 third-party renovation details inspection after water/electrical rough-in (electrical and plumbingrenovation details renovation details)","link":null},"plain_text":"Stage-1 third-party renovation details inspection after water/electrical rough-in (electrical and plumbingrenovation details renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 3 days of water+electrical rough-in completion and before any wall closure, an independent licensed renovation details performs a written inspection; standard fee forrenovation details 90-120㎡ unit ¥300-480 (¥10/㎡ forrenovation details); report covers ≥15 categories / ≥33 subitems / ≥420 checkpoints including PPR water pressure test ≥0.8 MPa hold 30 min with zero drop, circuit insulation resistance, conduit separation, conductor sizing per outlet; defects entered into change-order log within 24 h.","link":null},"plain_text":"Within 3 days of water+electrical rough-in completion and before any wall closure, an independent licensed renovation details performs a written inspection; standard fee forrenovation details 90-120㎡ unit ¥300-480 (¥10/㎡ forrenovation details); report covers ≥15 categories / ≥33 subitems / ≥420 checkpoints including PPR water pressure test ≥0.8 MPa hold 30 min with zero drop, circuit insulation resistance, conduit separation, conductor sizing per outlet; defects entered into change-order log within 24 h.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"waterproofing"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://blog.csdn.net/XJWLYF8888/article/details/127134401"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"wall closure done without renovation details visit — concealed joint discovered post-tile, 5× rework cost"},{"name":"water-pressure test only held 5 min instead of 30 min"},{"name":"verbal verbal-only finding not recorded in change-order log"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold waterproofing or wall closure until a written Stage-1 renovation details report is filed and defects are scheduled for remediation.","link":null},"plain_text":"Hold waterproofing or wall closure until a written Stage-1 renovation details report is filed and defects are scheduled for remediation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_tile_fcecbc98ef', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_tile_fcecbc98ef","link":null},"plain_text":"standard_tile_fcecbc98ef","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"tile"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-2 third-party renovation details inspection after masonry completion (masonryrenovation details renovation details)","link":null},"plain_text":"Stage-2 third-party renovation details inspection after masonry completion (masonryrenovation details renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 3 days of tile + grouting completion and before paint or cabinet install, an independent renovation details performs a tap-test inspection of every tile surface; hollow rate ≤ 5% project-wide and ≤ 15% on any single tile per GB 50210-2018; flatness ≤ 2 mm under 2 m straightedge; closed-water test repeated at 30 mm depth × ≥24 h post-tile; report fee ¥300-480 (renovation details) or ¥10/㎡ (renovation details), with photos + integrated repair list.","link":null},"plain_text":"Within 3 days of tile + grouting completion and before paint or cabinet install, an independent renovation details performs a tap-test inspection of every tile surface; hollow rate ≤ 5% project-wide and ≤ 15% on any single tile per GB 50210-2018; flatness ≤ 2 mm under 2 m straightedge; closed-water test repeated at 30 mm depth × ≥24 h post-tile; report fee ¥300-480 (renovation details) or ¥10/㎡ (renovation details), with photos + integrated repair list.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"paint"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://blog.csdn.net/XJWLYF8888/article/details/127134401"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"tile fell from wall at month 5 — never tap-tested before paint"},{"name":"no Stage-2 inspection — flatness defects covered by skirting board"},{"name":"second closed-water test skipped — leak surfaced after move-in"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold paint or cabinet install scheduling until the Stage-2 renovation details report is on file and remediation is closed.","link":null},"plain_text":"Hold paint or cabinet install scheduling until the Stage-2 renovation details report is on file and remediation is closed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_air_quality_04cda09d72', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_air_quality_04cda09d72","link":null},"plain_text":"standard_air_quality_04cda09d72","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CMA-accredited indoor-air testing timing rule — minimum 7-day post-completion delay + 12-hour closed-window pre-conditioning (CMArenovation detailstimewindow)","link":null},"plain_text":"CMA-accredited indoor-air testing timing rule — minimum 7-day post-completion delay + 12-hour closed-window pre-conditioning (CMArenovation detailstimewindow)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Testing must commence ≥7 calendar days after the last finishing activity (paint, glue, sealant, or new-furniture delivery); doors and windows closed for ≥12 h before sampling for the 3-pollutant panel (formaldehyde + benzene + TVOC), or ≥24 h before sampling for the 5-pollutant panel (adds toluene/xylene/ammonia/radon); air conditioner and ventilation off during the closed period; report turnaround 5-7 days; laboratory must hold valid CMA accreditation with certificate number on report.","link":null},"plain_text":"Testing must commence ≥7 calendar days after the last finishing activity (paint, glue, sealant, or new-furniture delivery); doors and windows closed for ≥12 h before sampling for the 3-pollutant panel (formaldehyde + benzene + TVOC), or ≥24 h before sampling for the 5-pollutant panel (adds toluene/xylene/ammonia/radon); air conditioner and ventilation off during the closed period; report turnaround 5-7 days; laboratory must hold valid CMA accreditation with certificate number on report.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"test run within 48 h of paint completion — formaldehyde under-detected (slow-release peak missed)"},{"name":"windows open during 12-h pre-conditioning — TVOC under-reported by ~40%"},{"name":"non-CMA lab used — report rejected by court in subsequent dispute"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: the lab''s CMA certificate number is on the report and sampling timestamp is at least 7 days after the last finishing entry in the construction log; reject otherwise.","link":null},"plain_text":"Required record: the lab''s CMA certificate number is on the report and sampling timestamp is at least 7 days after the last finishing entry in the construction log; reject otherwise.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_air_quality_c3d4f13af8', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_air_quality_c3d4f13af8","link":null},"plain_text":"standard_air_quality_c3d4f13af8","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"air_quality"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"CMA sampling-point density per room (CMArenovation details)","link":null},"plain_text":"CMA sampling-point density per room (CMArenovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Sampling points scaled to floor area per GB 50325-2020: ≤50 m² → 1 point per room; 50-100 m² → 2 points per room; >100 m² → 3-5 points per room; minimum one sample in each enclosed room (bedrooms, living room, kitchen, study); kitchen sampled separately due to combustion sources; sampling point ≥0.5 m from wall, ≥1.0 m above floor, ≥0.5 m from doors and windows; 3-pollutant panel fee ¥1,200 / 100 m² unit, 5-pollutant ¥2,000, per-point ¥500-800.","link":null},"plain_text":"Sampling points scaled to floor area per GB 50325-2020: ≤50 m² → 1 point per room; 50-100 m² → 2 points per room; >100 m² → 3-5 points per room; minimum one sample in each enclosed room (bedrooms, living room, kitchen, study); kitchen sampled separately due to combustion sources; sampling point ≥0.5 m from wall, ≥1.0 m above floor, ≥0.5 m from doors and windows; 3-pollutant panel fee ¥1,200 / 100 m² unit, 5-pollutant ¥2,000, per-point ¥500-800.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"third_party_inspection"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"GB 50325-2020"}},"source_url":{"type":"url","url":"https://www.mohurd.gov.cn/gongkai/zc/wjk/art/2020/art_17339_245708.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"whole-unit single-sample report — bedroom exceedance hidden by living-room dilution"},{"name":"kitchen not sampled separately — combustion contributors masked"},{"name":"sampling point next to window — value diluted by infiltration air"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Do not accept any indoor-air report that lacks per-room sampling locations or uses fewer than the minimum point count for the unit area.","link":null},"plain_text":"Do not accept any indoor-air report that lacks per-room sampling locations or uses fewer than the minimum point count for the unit area.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_plumbing_54e468529e', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_plumbing_54e468529e","link":null},"plain_text":"standard_plumbing_54e468529e","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"plumbing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Public-stack drain-line accessibility — inspection port and removable cabinet panel (renovation details)","link":null},"plain_text":"Public-stack drain-line accessibility — inspection port and removable cabinet panel (renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Where renovation encloses a shared/public drainage stack (renovation details) in a cabinet, soffit, or wall built-out, an accessible inspection port (renovation details ≥200 mm × 200 mm with removable cover) must be retained at every required maintenance point per CECS 168; cabinet panel over a stack must be screw-fixed (not glued) and labeled with a permanent tag indicating ''public drainage — do not seal''; owner signs an acknowledgment that refusal to allow stack access during a downstairs leak event shifts joint-and-several liability for downstream damage.","link":null},"plain_text":"Where renovation encloses a shared/public drainage stack (renovation details) in a cabinet, soffit, or wall built-out, an accessible inspection port (renovation details ≥200 mm × 200 mm with removable cover) must be retained at every required maintenance point per CECS 168; cabinet panel over a stack must be screw-fixed (not glued) and labeled with a permanent tag indicating ''public drainage — do not seal''; owner signs an acknowledgment that refusal to allow stack access during a downstairs leak event shifts joint-and-several liability for downstream damage.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"tile"},{"name":"cabinet"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"3rd-floor unit suffered ¥39,000+ ceiling damage from 4th-floor public stack leak; 4th-floor owner refused cabinet removal for inspection — court apportioned 50% liability to that owner"},{"name":"stack enclosed without inspection port — plumber chiseled tile to access, owner billed for restoration"},{"name":"tag missing — next owner / property manager sealed the access during refit"}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Hold tile/cabinet sign-off if a public-stack inspection port is missing or not labeled; record owner acknowledgment in the handover packet.","link":null},"plain_text":"Hold tile/cabinet sign-off if a public-stack inspection port is missing or not labeled; record owner acknowledgment in the handover packet.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_waterproofing_cf8a3cb844', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_waterproofing_cf8a3cb844","link":null},"plain_text":"standard_waterproofing_cf8a3cb844","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"waterproofing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"30-day post-handover closed-water re-test (water-retentionrenovation details 30renovation details)","link":null},"plain_text":"30-day post-handover closed-water re-test (water-retentionrenovation details 30renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At day 30 ±3 post-handover, repeat the closed-water test (≥30 mm water depth × ≥24 h) in every wet area; downstairs unit ceiling re-inspected on the same day in coordination with downstairs owner; test passes only if (a) water-level drop is explained by evaporation alone, (b) downstairs ceiling has no new stain or moisture spot, (c) no efflorescence at floor-wall joints in the tested room.","link":null},"plain_text":"At day 30 ±3 post-handover, repeat the closed-water test (≥30 mm water depth × ≥24 h) in every wet area; downstairs unit ceiling re-inspected on the same day in coordination with downstairs owner; test passes only if (a) water-level drop is explained by evaporation alone, (b) downstairs ceiling has no new stain or moisture spot, (c) no efflorescence at floor-wall joints in the tested room.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"test_report"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"initial closed-water test passed at handover but month-1 retest showed downstairs ceiling damp spot — vendor disputed liability without month-1 evidence"},{"name":"drainage-pipe leak masked by floor void — surfaced only after 30 days of normal use"},{"name":"downstairs owner refused day-30 access — leak progressed to month-3 and damages compounded"}]},"evidence_register":{"type":"select","select":{"name":"project_calendar"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Auto-schedule a day-30 closed-water retest on the calendar at handover; record results in the warranty register and pursue immediate remediation on any positive.","link":null},"plain_text":"Auto-schedule a day-30 closed-water retest on the calendar at handover; record results in the warranty register and pursue immediate remediation on any positive.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_waterproofing_b79bb0b581', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_waterproofing_b79bb0b581","link":null},"plain_text":"standard_waterproofing_b79bb0b581","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"waterproofing"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"90-day post-handover closed-water + drainage inspection (water-retention+renovation details90renovation details)","link":null},"plain_text":"90-day post-handover closed-water + drainage inspection (water-retention+renovation details90renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At day 90 ±7 post-handover, repeat closed-water test in shower zones (≥24 h hold) AND perform a 30-minute high-volume drainage stress test (run shower + sink + floor drain simultaneously at full flow) while downstairs ceiling is observed; record any anomaly in the warranty register; failure triggers root-cause analysis covering (a) waterproofing membrane integrity, (b) public-stack joint, (c) floor-tile grout permeability, (d) sealant aging.","link":null},"plain_text":"At day 90 ±7 post-handover, repeat closed-water test in shower zones (≥24 h hold) AND perform a 30-minute high-volume drainage stress test (run shower + sink + floor drain simultaneously at full flow) while downstairs ceiling is observed; record any anomaly in the warranty register; failure triggers root-cause analysis covering (a) waterproofing membrane integrity, (b) public-stack joint, (c) floor-tile grout permeability, (d) sealant aging.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"test_report"}},"blocks_next_phases":{"type":"multi_select","multi_select":[]},"source_authority":{"type":"select","select":{"name":"shanghai_court_2024"}},"source_url":{"type":"url","url":"https://hshfy.sh.cn/shfy/web/xxnr.jsp"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"leak surfaced at month 3 — root cause was public-stack joint, not unit waterproofing, but no inspection-port access caused 2-week diagnostic delay"},{"name":"shower drain accumulated hair clog — drainage stress test would have surfaced at month 1"},{"name":"downstairs ceiling stain appeared at month 4 — no day-90 record to anchor warranty claim"}]},"evidence_register":{"type":"select","select":{"name":"project_calendar"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Auto-schedule a day-90 closed-water + drainage stress test on the calendar; require downstairs owner present or remote-video confirmation.","link":null},"plain_text":"Auto-schedule a day-90 closed-water + drainage stress test on the calendar; require downstairs owner present or remote-video confirmation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_contract_b4468bf59e', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_contract_b4468bf59e","link":null},"plain_text":"standard_contract_b4468bf59e","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Quote benchmarking against 2025 Shanghai market reference bands (renovation details)","link":null},"plain_text":"Quote benchmarking against 2025 Shanghai market reference bands (renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before signing, owner cross-checks the vendor''s quote against 2025 Shanghai market reference bands: renovation detailsrenovation ¥500-800/㎡; renovation detailsrenovation ¥1,000-1,500/㎡; renovation details (renovation details+renovation details) ¥1,100-1,500/㎡; renovation details (renovation details+renovation details+primary materials) ¥1,800-2,500/㎡ (mid ¥1,400-2,000/㎡); renovation details ¥3,000-5,000/㎡; quotes >25% above the upper band of the applicable tier require itemized justification; quotes >15% below the lower band trigger a hidden-add-on risk flag (typical change order rate 42%, with electrical and plumbingrenovation details 60%+ of overruns).","link":null},"plain_text":"Before signing, owner cross-checks the vendor''s quote against 2025 Shanghai market reference bands: renovation detailsrenovation ¥500-800/㎡; renovation detailsrenovation ¥1,000-1,500/㎡; renovation details (renovation details+renovation details) ¥1,100-1,500/㎡; renovation details (renovation details+renovation details+primary materials) ¥1,800-2,500/㎡ (mid ¥1,400-2,000/㎡); renovation details ¥3,000-5,000/㎡; quotes >25% above the upper band of the applicable tier require itemized justification; quotes >15% below the lower band trigger a hidden-add-on risk flag (typical change order rate 42%, with electrical and plumbingrenovation details 60%+ of overruns).","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"},{"name":"tile"},{"name":"final_handover"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://www.163.com/dy/article/K7J9B3L30556EG2C.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"renovation details quote at ¥1,200/㎡ — final cost ¥2,400/㎡ via 38% change order, mostly electrical and plumbing and renovation details"},{"name":"renovation details not recorded — owner unable to challenge renovation details +8% premium atrenovation details"},{"name":"main-material upgrades ''recommended'' then forced — owner paid 22% above signed price"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: signed benchmark-comparison sheet exists in the contract packet; flag any change order ratio at completion that exceeds 15% of the original contract value for owner-vendor reconciliation.","link":null},"plain_text":"Required record: signed benchmark-comparison sheet exists in the contract packet; flag any change order ratio at completion that exceeds 15% of the original contract value for owner-vendor reconciliation.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_contract_f9e7827dff', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_contract_f9e7827dff","link":null},"plain_text":"standard_contract_f9e7827dff","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"contract"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Seasonal-premium and labor-availability disclosure (renovation details+renovation details)","link":null},"plain_text":"Seasonal-premium and labor-availability disclosure (renovation details+renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Contract explicitly discloses: (a) base period vs peak-season (May, September) labor premium (typical +5-8% over base); (b) any post-Spring-Festival start-up queue (typical 4-8 weeks); (c) committed start date with named project manager; (d) penalty clause for vendor-side delay beyond 14 days at ≥0.05% of contract value per day; quote that omits any of these triggers a contract-revision request before signing.","link":null},"plain_text":"Contract explicitly discloses: (a) base period vs peak-season (May, September) labor premium (typical +5-8% over base); (b) any post-Spring-Festival start-up queue (typical 4-8 weeks); (c) committed start date with named project manager; (d) penalty clause for vendor-side delay beyond 14 days at ≥0.05% of contract value per day; quote that omits any of these triggers a contract-revision request before signing.","annotations":{},"href":null}]},"required_evidence":{"type":"select","select":{"name":"written_owner_signoff"}},"blocks_next_phases":{"type":"multi_select","multi_select":[{"name":"pre_demolition"},{"name":"rough_in"}]},"source_authority":{"type":"select","select":{"name":"industry_practice"}},"source_url":{"type":"url","url":"https://www.to8to.com/yezhu/z326107.html"},"typical_failure_modes":{"type":"multi_select","multi_select":[{"name":"May start with no disclosed premium — labor cost surged 8% mid-project as ''market adjustment''"},{"name":"post-Spring-Festival start queued 6 weeks behind committed date — project manager simultaneously running 4 sites"},{"name":"no delay penalty — project ran 28 days over with zero compensation (industry average overrun)"}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: the signed contract contains the four disclosure items; reject vendor''s standard contract template if any are missing.","link":null},"plain_text":"Required record: the signed contract contains the four disclosure items; reject vendor''s standard contract template if any are missing.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('standard_final_handover_9eb95caa2d', 'notion-db-inspection-standards', '{"standard_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"standard_final_handover_9eb95caa2d","link":null},"plain_text":"standard_final_handover_9eb95caa2d","annotations":{},"href":null}]},"phase":{"type":"select","select":{"name":"final_handover"}},"check_item":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Stage-3 third-party renovation details inspection before final handover (renovation details renovation details)","link":null},"plain_text":"Stage-3 third-party renovation details inspection before final handover (renovation details renovation details)","annotations":{},"href":null}]},"pass_criteria":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within 7 days before the scheduled final-handover signing, an independent renovation details performs a complete pre-handover inspection covering 15 major + 33 sub-categories per industry guideline; minimum scope includes air-quality, water-pressure 0.8 MPa × 30 min, closed-water ≥24 h, tile tap-test, electrical RCD trip-time, drainage stress test, and Shanghai-specific damp-proofing checks; fee ¥10/㎡ for renovation details or ¥300-480 fixed forrenovation details 90-150 ㎡; report incorporates Stage-1 and Stage-2 findings and closes them or escalates them to warranty register.","link":null},"plain_text":"Within 7 days before the scheduled final-handover signing, an independent renovation details performs a complete pre-handover inspection covering 15 major + 33 sub-categories per industry guideline; minimum scope includes air-quality, water-pressure 0.8 MPa × 30 min, closed-water ≥24 h, tile tap-test, electrical RCD trip-time, drainage stress test, and Shanghai-specific damp-proofing checks; fee ¥10/㎡ for renovation details or ¥300-480 fixed forrenovation det