INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_80b48fedd23f', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_80b48fedd23f","link":null},"plain_text":"rule_80b48fedd23f","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"structural"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Altering the building main structure or load-bearing structure without a qualified design unit''s plan is prohibited.","link":null},"plain_text":"Altering the building main structure or load-bearing structure without a qualified design unit''s plan is prohibited.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Do not include scope items that touch load-bearing walls; if needed, engage a qualified design unit and obtain approval first.","link":null},"plain_text":"Do not include scope items that touch load-bearing walls; if needed, engage a qualified design unit and obtain approval first.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before any structural work","link":null},"plain_text":"Before any structural work","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Order to restore + fines; safety liability if structure is damaged.","link":null},"plain_text":"Order to restore + fines; safety liability if structure is damaged.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"reno