INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_43265f9f8edc', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_43265f9f8edc","link":null},"plain_text":"rule_43265f9f8edc","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"waterproofing"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Converting a room or balcony that has no waterproofing requirement into a bathroom or kitchen is prohibited.","link":null},"plain_text":"Converting a room or balcony that has no waterproofing requirement into a bathroom or kitchen is prohibited.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Keep wet-area locations to rooms originally designed as wet areas; otherwise require a qualified design review.","link":null},"plain_text":"Keep wet-area locations to rooms originally designed as wet areas; otherwise require a qualified design review.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before scope freeze","link":null},"plain_text":"Before scope freeze","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Order to restore + downstream water-damage liability to neighbors.","link":null},"plain_text":"Order to restore + downstream water-damage liability to neighbors.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation detailsrenovationrenovation details Art. 5(2)","link":