INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_db22dcb64091', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_db22dcb64091","link":null},"plain_text":"rule_db22dcb64091","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"gas"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Modifying gas pipes or fixtures during renovation requires prior approval from the gas management unit.","link":null},"plain_text":"Modifying gas pipes or fixtures during renovation requires prior approval from the gas management unit.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Engage the city gas company; obtain written approval; only licensed gas installers may touch the pipework.","link":null},"plain_text":"Engage the city gas company; obtain written approval; only licensed gas installers may touch the pipework.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before any kitchen rough-in that touches the gas line","link":null},"plain_text":"Before any kitchen rough-in that touches the gas line","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Order to restore + safety risk; insurance void.","link":null},"plain_text":"Order to restore + safety risk; insurance void.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation detailsrenovationrenovation details Art. 6(4)","link":