INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_413fbd3f8c04', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_413fbd3f8c04","link":null},"plain_text":"rule_413fbd3f8c04","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"facade"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Changing the exterior facade or opening doors / windows on non-load-bearing exterior walls requires planning-authority approval.","link":null},"plain_text":"Changing the exterior facade or opening doors / windows on non-load-bearing exterior walls requires planning-authority approval.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Avoid scope that alters the exterior; if window opening sizes change, file with the planning authority first.","link":null},"plain_text":"Avoid scope that alters the exterior; if window opening sizes change, file with the planning authority first.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before any window/door change order","link":null},"plain_text":"Before any window/door change order","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Forced restoration + fines.","link":null},"plain_text":"Forced restoration + fines.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation detailsrenovationrenovation details Art. 6(2)","link":null},"plain_text