INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_8a73ec5482a7', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_8a73ec5482a7","link":null},"plain_text":"rule_8a73ec5482a7","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"noise_hours"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In Shanghai residential communities, noisy operations (knocking, chiseling, sawing, drilling) are prohibited from 18:00 to 08:00 daily and all day on statutory holidays.","link":null},"plain_text":"In Shanghai residential communities, noisy operations (knocking, chiseling, sawing, drilling) are prohibited from 18:00 to 08:00 daily and all day on statutory holidays.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Schedule noisy work strictly between 08:00 and 18:00 on non-holiday workdays / weekends; quiet activities (cleaning, measurement, delivery) may run outside.","link":null},"plain_text":"Schedule noisy work strictly between 08:00 and 18:00 on non-holiday workdays / weekends; quiet activities (cleaning, measurement, delivery) may run outside.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Daily, throughout construction","link":null},"plain_text":"Daily, throughout construction","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property warning; neighbor complaint escalation; ordered stoppage.","link":null},"plain_text":"Property warning; neighbor complaint escalation; ordered stoppage.","annotations":{},"href":null}]},"so