INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_a11c8821815b', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_a11c8821815b","link":null},"plain_text":"rule_a11c8821815b","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"filing"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before renovation registration, the owner must submit the decoration contractor, construction period, and construction drawings / plan to property management.","link":null},"plain_text":"Before renovation registration, the owner must submit the decoration contractor, construction period, and construction drawings / plan to property management.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Prepare a packet with: contractor business license / qualifications, construction period, drawings, and signed decoration agreement; submit to property.","link":null},"plain_text":"Prepare a packet with: contractor business license / qualifications, construction period, drawings, and signed decoration agreement; submit to property.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before construction starts","link":null},"plain_text":"Before construction starts","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property may refuse to issue construction pass; workers / materials denied entry.","link":null},"plain_text":"Property may refuse to issue construction pass; workers / materials denied entry.","annotations":{},"href":null}]},"source_url":{"t