INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_723d4192f27d', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_723d4192f27d","link":null},"plain_text":"rule_723d4192f27d","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"filing"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"The decoration management agreement must cover prohibited acts, waste stacking and removal, construction hours, and fee items.","link":null},"plain_text":"The decoration management agreement must cover prohibited acts, waste stacking and removal, construction hours, and fee items.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Ensure the signed agreement explicitly lists prohibited acts, waste disposal arrangements, work hours, and any fees.","link":null},"plain_text":"Ensure the signed agreement explicitly lists prohibited acts, waste disposal arrangements, work hours, and any fees.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before construction starts","link":null},"plain_text":"Before construction starts","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Disputes over noise / waste / damages with no written basis; possible work suspension.","link":null},"plain_text":"Disputes over noise / waste / damages with no written basis; possible work suspension.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"source_title":{"type":"ri