INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_c214b2726417', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_c214b2726417","link":null},"plain_text":"rule_c214b2726417","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"waste"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Where a property management company is hired, it is the responsible party for renovation-waste collection points; otherwise the owner / unit is responsible.","link":null},"plain_text":"Where a property management company is hired, it is the responsible party for renovation-waste collection points; otherwise the owner / unit is responsible.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Confirm with property where the designated collection point is, or ask the property to direct the renovator to a government-designated location.","link":null},"plain_text":"Confirm with property where the designated collection point is, or ask the property to direct the renovator to a government-designated location.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before demolition / waste-producing work","link":null},"plain_text":"Before demolition / waste-producing work","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"¥1,000-¥10,000 for missing collection points.","link":null},"plain_text":"¥1,000-¥10,000 for missing collection points.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/nw42535/20200823/00