INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_d070941c8952', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_d070941c8952","link":null},"plain_text":"rule_d070941c8952","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"district_putuo"}},"topic":{"type":"select","select":{"name":"noise_enforcement"}},"authority_level":{"type":"select","select":{"name":"district_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Putuo unifies renovation-noise complaints into the 12345 city hotline; complaints from this channel are tracked and aggregated by the district.","link":null},"plain_text":"Putuo unifies renovation-noise complaints into the 12345 city hotline; complaints from this channel are tracked and aggregated by the district.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In Putuo, if a neighbor mentions calling 12345, treat as an official complaint and escalate the response (pause work, written reply same day).","link":null},"plain_text":"In Putuo, if a neighbor mentions calling 12345, treat as an official complaint and escalate the response (pause work, written reply same day).","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Same-day on any 12345 complaint","link":null},"plain_text":"Same-day on any 12345 complaint","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Aggregated complaint count can trigger district-level intervention.","link":null},"plain_text":"Aggregated complaint count can trigger district-level intervention.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shpt.gov.cn/fgj-zfbm/xwdt-fgj/20