INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_9de47f001f83', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_9de47f001f83","link":null},"plain_text":"rule_9de47f001f83","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"district_songjiang"}},"topic":{"type":"select","select":{"name":"waste"}},"authority_level":{"type":"select","select":{"name":"district_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In Songjiang, renovation waste must be transported only to district-designated disposal facilities; self-handling or third-party diversion is prohibited.","link":null},"plain_text":"In Songjiang, renovation waste must be transported only to district-designated disposal facilities; self-handling or third-party diversion is prohibited.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Confirm with property that the chosen hauler routes to the district-designated facility; obtain the facility receipt for each load.","link":null},"plain_text":"Confirm with property that the chosen hauler routes to the district-designated facility; obtain the facility receipt for each load.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Each waste-cart dispatch","link":null},"plain_text":"Each waste-cart dispatch","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Pickup refused; fines for unauthorized disposal route.","link":null},"plain_text":"Pickup refused; fines for unauthorized disposal route.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.songjiang.gov.cn/govxxgk/SHSJ22/2023-05-06/6591b7c0-a06e-47d2-afd0-7c013c3f58db.ht