INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_b8f18b0510bf', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_b8f18b0510bf","link":null},"plain_text":"rule_b8f18b0510bf","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"community_business"}},"topic":{"type":"select","select":{"name":"weekend_quiet"}},"authority_level":{"type":"select","select":{"name":"community_management"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Many Shanghai renovation details prohibit noisy renovation work all weekend (Sat+Sun), even though city rules allow weekend work between 08:00-18:00.","link":null},"plain_text":"Many Shanghai renovation details prohibit noisy renovation work all weekend (Sat+Sun), even though city rules allow weekend work between 08:00-18:00.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before scheduling weekend work, get written confirmation from property whether the renovation details allows weekend noise; default-assume NOT allowed in high-density communities.","link":null},"plain_text":"Before scheduling weekend work, get written confirmation from property whether the renovation details allows weekend noise; default-assume NOT allowed in high-density communities.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before any weekend noisy-work scheduling","link":null},"plain_text":"Before any weekend noisy-work scheduling","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property stoppage; neighbor complaint.","link":null},"plain_text":"Property stoppage; neighbor complaint.","annotations":{},"href":null}]},"source_url":{"type":"ur