INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_4aeb57cf11dd', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_4aeb57cf11dd","link":null},"plain_text":"rule_4aeb57cf11dd","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"aging_friendly"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai residents aged 60+ are eligible for state-subsidized home adaptation (anti-slip, grab bars, gas/fire alarms); subsidy rate depends on household category — full coverage (renovation details), 80% (low-income), 50% (80+ with sub-pension income), 40% (care-level 2+ / hardship); cumulative cap ¥5,000 per household over 3 years.","link":null},"plain_text":"Shanghai residents aged 60+ are eligible for state-subsidized home adaptation (anti-slip, grab bars, gas/fire alarms); subsidy rate depends on household category — full coverage (renovation details), 80% (low-income), 50% (80+ with sub-pension income), 40% (care-level 2+ / hardship); cumulative cap ¥5,000 per household over 3 years.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"If the renovation scope includes aging adaptation for a 60+ resident, file a subsidy application with the district renovation details (civil affairs) before purchase / installation; engage a designated renovation details service unit listed in the official catalog.","link":null},"plain_text":"If the renovation scope includes aging adaptation for a 60+ resident, file a subsidy application with the district renovation details (civil affairs) before purchase / installation; engage a designated renovation details service unit listed in the official catalog.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before purchasing aging-friendly hardware/installation","link":null},"plain_text":"Before purchasing aging-friendly hardware/installation","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Subsidy denied (cannot back-apply after installation); cumulative cap exceeded → out-of-pocket cost.","link":null},"plain_text":"Subsidy denied (cannot back-apply after installation); cumulative cap exceeded → out-of-pocket cost.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/jjylfwsjzc/20230404/1dcce434339a45778c725f68130b098b.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghairenovation details (2023-04-04)","link":null},"plain_text":"Shanghairenovation details (2023-04-04)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: the aging-friendly scope is paired with a renovation details subsidy filing record before any aging-friendly material is purchased / installed.","link":null},"plain_text":"Required record: the aging-friendly scope is paired with a renovation details subsidy filing record before any aging-friendly material is purchased / installed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_ea5824fe9948', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_ea5824fe9948","link":null},"plain_text":"rule_ea5824fe9948","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"aging_friendly"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"2024-10 renovation details activity opened a 30% universal subsidy (max ¥3,000) to any Shanghai 60+ resident not covered by the four targeted brackets; effective through end of 2024 and extended into 2025.","link":null},"plain_text":"2024-10 renovation details activity opened a 30% universal subsidy (max ¥3,000) to any Shanghai 60+ resident not covered by the four targeted brackets; effective through end of 2024 and extended into 2025.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Confirm the 60+ resident is registered with renovation details activity at their renovation details; combine with district-level top-ups (e.g., renovation details renovation details) where eligible.","link":null},"plain_text":"Confirm the 60+ resident is registered with renovation details activity at their renovation details; combine with district-level top-ups (e.g., renovation details renovation details) where eligible.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Subsidy claim before installation invoice issued","link":null},"plain_text":"Subsidy claim before installation invoice issued","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"30% subsidy denied after-the-fact; cannot stack with the 4 targeted brackets above the ¥5,000 cap.","link":null},"plain_text":"30% subsidy denied after-the-fact; cannot stack with the 4 targeted brackets above the ¥5,000 cap.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/xbhygq/20241008/a002192eb2904a6b9b2c0073a8ab9ac5.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghairenovation details 2024-10 renovation details renovation details (renovation details)","link":null},"plain_text":"Shanghairenovation details 2024-10 renovation details renovation details (renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Project record requires filed a renovation details activity registration before the aging-friendly install date if the resident is in the universal bracket.","link":null},"plain_text":"Project record requires filed a renovation details activity registration before the aging-friendly install date if the resident is in the universal bracket.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_9513b0714a5d', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_9513b0714a5d","link":null},"plain_text":"rule_9513b0714a5d","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"aging_friendly"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"2025-04 update consolidates the three packages: renovation details (grab bars / anti-slip / gas+fire alarm) / renovation details (tub-to-shower, anti-slip, shower equipment) / renovation details (smart-home + health monitoring + circuit replacement); each unit must come from the renovation details designated catalog.","link":null},"plain_text":"2025-04 update consolidates the three packages: renovation details (grab bars / anti-slip / gas+fire alarm) / renovation details (tub-to-shower, anti-slip, shower equipment) / renovation details (smart-home + health monitoring + circuit replacement); each unit must come from the renovation details designated catalog.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Select aging-friendly hardware/install items only from the renovation details designated catalog; reject off-catalog items if subsidy is to be claimed.","link":null},"plain_text":"Select aging-friendly hardware/install items only from the renovation details designated catalog; reject off-catalog items if subsidy is to be claimed.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Pre-purchase review","link":null},"plain_text":"Pre-purchase review","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Off-catalog items disqualified from subsidy; package classification mistakes → wrong subsidy rate.","link":null},"plain_text":"Off-catalog items disqualified from subsidy; package classification mistakes → wrong subsidy rate.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/xbhygq/20250408/7d4c22d155714073ac6bc76f3c30cb3d.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"2025 Shanghairenovation details renovation details (2025-04-08 renovation details)","link":null},"plain_text":"2025 Shanghairenovation details renovation details (2025-04-08 renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Escalate any aging-friendly material whose brand is not in the renovation details designated catalog when subsidy is being claimed.","link":null},"plain_text":"Escalate any aging-friendly material whose brand is not in the renovation details designated catalog when subsidy is being claimed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_1f508f2754f5', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_1f508f2754f5","link":null},"plain_text":"rule_1f508f2754f5","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"filing"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"From 2025-09-25, any renovation details (existing building) renovation must follow the published construction-procedure: filing → design review → construction permit (where applicable) → quality+safety inspection → completion acceptance; deviations void filing.","link":null},"plain_text":"From 2025-09-25, any renovation details (existing building) renovation must follow the published construction-procedure: filing → design review → construction permit (where applicable) → quality+safety inspection → completion acceptance; deviations void filing.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For projects exceeding the residential exemption threshold, follow the 5-step program; for residential, ensure the filing + design + completion-acceptance steps are documented.","link":null},"plain_text":"For projects exceeding the residential exemption threshold, follow the 5-step program; for residential, ensure the filing + design + completion-acceptance steps are documented.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Throughout project life cycle","link":null},"plain_text":"Throughout project life cycle","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Filing voided; construction halt order; completion certificate denied.","link":null},"plain_text":"Filing voided; construction halt order; completion certificate denied.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://zjw.sh.gov.cn/gfxwj/20250925/ff0c97d945a243cc9133ca6f52d6d326.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghairenovation details renovation detailsrenovationrenovation details (2025-09-25)","link":null},"plain_text":"Shanghairenovation details renovation detailsrenovationrenovation details (2025-09-25)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: each project has documented evidence of: filing record, design review note, and completion-acceptance record.","link":null},"plain_text":"Required record: each project has documented evidence of: filing record, design review note, and completion-acceptance record.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_3cd14b458abc', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_3cd14b458abc","link":null},"plain_text":"rule_3cd14b458abc","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_jingan_district"}},"topic":{"type":"select","select":{"name":"commercial_filing"}},"authority_level":{"type":"select","select":{"name":"district_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Within renovation details, non-residential renovation projects with cost ≥¥1,000,000 OR floor area ≥300㎡ must complete the consolidated renovation detailsrenovationrenovation details (one-stop) filing — combining housing, fire, safety, and pass-issuance into a single window.","link":null},"plain_text":"Within renovation details, non-residential renovation projects with cost ≥¥1,000,000 OR floor area ≥300㎡ must complete the consolidated renovation detailsrenovationrenovation details (one-stop) filing — combining housing, fire, safety, and pass-issuance into a single window.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For commercial fit-out within renovation details, submit the renovation details filing packet (design drawings, contractor quals, fire plan, safety plan); track the unified case-ID.","link":null},"plain_text":"For commercial fit-out within renovation details, submit the renovation details filing packet (design drawings, contractor quals, fire plan, safety plan); track the unified case-ID.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before construction starts","link":null},"plain_text":"Before construction starts","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Construction barred; downstream fire inspection refused; commercial property may withhold occupancy.","link":null},"plain_text":"Construction barred; downstream fire inspection refused; commercial property may withhold occupancy.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://zjw.sh.gov.cn/gfxwj/20250925/ff0c97d945a243cc9133ca6f52d6d326.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation details renovation detailsrenovationrenovation details renovation details (≥100renovation details OR ≥300㎡ renovation detailsrenovation)","link":null},"plain_text":"renovation details renovation detailsrenovationrenovation details renovation details (≥100renovation details OR ≥300㎡ renovation detailsrenovation)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For renovation details commercial projects ≥¥1M OR ≥300㎡, verify a renovation details case-ID exists in the filing record before any construction-window calendar event is confirmed.","link":null},"plain_text":"For renovation details commercial projects ≥¥1M OR ≥300㎡, verify a renovation details case-ID exists in the filing record before any construction-window calendar event is confirmed.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_c833000639f6', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_c833000639f6","link":null},"plain_text":"rule_c833000639f6","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"deposit"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Per municipal regulations, property service companies are not legally permitted to collect a renovation deposit from owners. Common practice (≈70-80% of communities) still collects ¥2,000-5,000 — owners should review the legality before paying.","link":null},"plain_text":"Per municipal regulations, property service companies are not legally permitted to collect a renovation deposit from owners. Common practice (≈70-80% of communities) still collects ¥2,000-5,000 — owners should review the legality before paying.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before paying any ''renovation deposit'', request the property''s written basis and verify against the municipal regulation; keep payment receipts.","link":null},"plain_text":"Before paying any ''renovation deposit'', request the property''s written basis and verify against the municipal regulation; keep payment receipts.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before paying deposit","link":null},"plain_text":"Before paying deposit","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Illegal deposit collection → reclaim via 12345 / housing authority complaint; lack of receipt makes refund hard.","link":null},"plain_text":"Illegal deposit collection → reclaim via 12345 / housing authority complaint; lack of receipt makes refund hard.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation details renovationrenovation details renovation details vs Shanghairenovation details renovation details","link":null},"plain_text":"renovation details renovationrenovation details renovation details vs Shanghairenovation details renovation details","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_correspondence"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Escalate any ''renovation deposit'' charge from property without a written legal basis; require receipt for the project coordinator to retain.","link":null},"plain_text":"Escalate any ''renovation deposit'' charge from property without a written legal basis; require receipt for the project coordinator to retain.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_fb9fb7b9da4c', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_fb9fb7b9da4c","link":null},"plain_text":"rule_fb9fb7b9da4c","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"deposit"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"If a deposit is collected: refund must occur within 3 months of work completion; for centrally-heated/cooled communities, within 6 months (allowing heating/cooling-season verification).","link":null},"plain_text":"If a deposit is collected: refund must occur within 3 months of work completion; for centrally-heated/cooled communities, within 6 months (allowing heating/cooling-season verification).","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Confirm in writing the refund timeline at deposit collection; track the 3/6-month refund clock from completion certificate date.","link":null},"plain_text":"Confirm in writing the refund timeline at deposit collection; track the 3/6-month refund clock from completion certificate date.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"≤3 months (≤6 months for centrally-heated/cooled communities) after completion","link":null},"plain_text":"≤3 months (≤6 months for centrally-heated/cooled communities) after completion","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Late refund → claim via 12345 / housing authority / civil court.","link":null},"plain_text":"Late refund → claim via 12345 / housing authority / civil court.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai renovationrenovation details renovation details renovation details (renovation details)","link":null},"plain_text":"Shanghai renovationrenovation details renovation details renovation details (renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_calendar"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: refund-due-date calendar event exists at completion + 3 (or 6) months for any project with a deposit recorded.","link":null},"plain_text":"Required record: refund-due-date calendar event exists at completion + 3 (or 6) months for any project with a deposit recorded.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_3bf4706fce4b', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_3bf4706fce4b","link":null},"plain_text":"rule_3bf4706fce4b","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"property_pass"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Renovation worker / vehicle entry passes issued by property must not exceed ¥10 per pass; any higher charge can be challenged.","link":null},"plain_text":"Renovation worker / vehicle entry passes issued by property must not exceed ¥10 per pass; any higher charge can be challenged.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Verify the per-pass fee at issuance; keep receipt; refuse payment above ¥10.","link":null},"plain_text":"Verify the per-pass fee at issuance; keep receipt; refuse payment above ¥10.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At pass issuance","link":null},"plain_text":"At pass issuance","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Overcharge → reclaim via 12345; affects worker entry schedule.","link":null},"plain_text":"Overcharge → reclaim via 12345; affects worker entry schedule.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/gwk/search/content/a03420d81639493db42343592087bb91"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai property managementrenovation details renovation details renovation details (renovation details renovation details)","link":null},"plain_text":"Shanghai property managementrenovation details renovation details renovation details (renovation details renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Escalate any property pass charge exceeding ¥10 per pass in the cost log.","link":null},"plain_text":"Escalate any property pass charge exceeding ¥10 per pass in the cost log.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_5d2d0c1af4ed', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_5d2d0c1af4ed","link":null},"plain_text":"rule_5d2d0c1af4ed","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"structural"}},"authority_level":{"type":"select","select":{"name":"district_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Damaging a load-bearing structure during renovation triggers: order to restore + fine of ¥10,000-¥100,000 (general) OR ¥100,000-¥200,000 (severe); plus civil liability to neighbors + potential criminal liability in extreme cases.","link":null},"plain_text":"Damaging a load-bearing structure during renovation triggers: order to restore + fine of ¥10,000-¥100,000 (general) OR ¥100,000-¥200,000 (severe); plus civil liability to neighbors + potential criminal liability in extreme cases.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Reject any quote/scope item that proposes removing, weakening, or expanding openings in a load-bearing wall; if uncertain, engage a renovation details (qualified inspector).","link":null},"plain_text":"Reject any quote/scope item that proposes removing, weakening, or expanding openings in a load-bearing wall; if uncertain, engage a renovation details (qualified inspector).","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At scope-freeze and before any wall work","link":null},"plain_text":"At scope-freeze and before any wall work","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"¥10,000-¥200,000 fine + restoration cost + neighbor civil claims; possible criminal liability.","link":null},"plain_text":"¥10,000-¥200,000 fine + restoration cost + neighbor civil claims; possible criminal liability.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shpt.gov.cn/gqjd-jiedaozhen/sqdt-sqzc-gqjd/20231222/930725.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation details load-bearing wallrenovation details (renovation details renovation details)","link":null},"plain_text":"renovation details load-bearing wallrenovation details (renovation details renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Escalate any scope/quote line touching a load-bearing wall; require a structural-engineer note in the file before approving.","link":null},"plain_text":"Escalate any scope/quote line touching a load-bearing wall; require a structural-engineer note in the file before approving.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_84fc5f8938b6', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_84fc5f8938b6","link":null},"plain_text":"rule_84fc5f8938b6","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_high_end_community_practice"}},"topic":{"type":"select","select":{"name":"neighbor_notice"}},"authority_level":{"type":"select","select":{"name":"committee_practice"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"In premium / historic communities, written consent from immediate neighbors (above / below / left / right) is required before noisy construction or wall work; without it, property may withhold the construction pass.","link":null},"plain_text":"In premium / historic communities, written consent from immediate neighbors (above / below / left / right) is required before noisy construction or wall work; without it, property may withhold the construction pass.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Obtain four-direction neighbor consent letters (signed + dated) before the first noisy work day; file copies with property.","link":null},"plain_text":"Obtain four-direction neighbor consent letters (signed + dated) before the first noisy work day; file copies with property.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before first noisy work day","link":null},"plain_text":"Before first noisy work day","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Property denies construction pass; neighbor complaints escalate via 12345 / housing authority.","link":null},"plain_text":"Property denies construction pass; neighbor complaints escalate via 12345 / housing authority.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shpt.gov.cn/gqjd-jiedaozhen/sqdt-sqzc-gqjd/20231222/930725.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation details renovation details (renovation details renovation details)","link":null},"plain_text":"renovation details renovation details (renovation details renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_correspondence"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For premium-community projects, verify all four neighbor consent letters are in the filing packet before any noisy-work calendar event.","link":null},"plain_text":"For premium-community projects, verify all four neighbor consent letters are in the filing packet before any noisy-work calendar event.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_d90c0d174de2', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_d90c0d174de2","link":null},"plain_text":"rule_d90c0d174de2","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"gas"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Any gas-pipe addition, relocation, alteration, meter resize, or removal requires application to the city gas company (96511) with: applicant ID + gas-account holder ID; for shared-use locations, written consent from co-users OR housing-authority certificate; only licensed gas installers may perform the work.","link":null},"plain_text":"Any gas-pipe addition, relocation, alteration, meter resize, or removal requires application to the city gas company (96511) with: applicant ID + gas-account holder ID; for shared-use locations, written consent from co-users OR housing-authority certificate; only licensed gas installers may perform the work.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"File the gas-modification application at the regional gas service window before kitchen rough-in; engage a licensed gas installer; for any DIY-routed pipe, schedule the mandatory gas-company re-inspection.","link":null},"plain_text":"File the gas-modification application at the regional gas service window before kitchen rough-in; engage a licensed gas installer; for any DIY-routed pipe, schedule the mandatory gas-company re-inspection.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before kitchen rough-in; re-inspection before kitchen sealing","link":null},"plain_text":"Before kitchen rough-in; re-inspection before kitchen sealing","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Re-inspection failure → gas supply may be suspended; un-certified work voids gas insurance.","link":null},"plain_text":"Re-inspection failure → gas supply may be suspended; un-certified work voids gas insurance.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://sh.bendibao.com/cyfw/2015520/132318.shtm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghairenovation details applicationrenovation details","link":null},"plain_text":"Shanghairenovation details applicationrenovation details","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_file"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: gas-company application record + (post-work) re-inspection certificate exist before kitchen rough-in closes.","link":null},"plain_text":"Required record: gas-company application record + (post-work) re-inspection certificate exist before kitchen rough-in closes.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_5f6e807d0c12', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_5f6e807d0c12","link":null},"plain_text":"rule_5f6e807d0c12","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"gas"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Old communities still on bottled-LPG must complete piped-gas replacement under the municipal program; bottled-LPG sites scheduled for replacement cannot install new bottled fixtures during renovation.","link":null},"plain_text":"Old communities still on bottled-LPG must complete piped-gas replacement under the municipal program; bottled-LPG sites scheduled for replacement cannot install new bottled fixtures during renovation.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For renovation in scheduled-replacement communities, confirm the piped-gas replacement timeline before kitchen design; do not procure bottled-LPG fixtures.","link":null},"plain_text":"For renovation in scheduled-replacement communities, confirm the piped-gas replacement timeline before kitchen design; do not procure bottled-LPG fixtures.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Before kitchen design / appliance procurement","link":null},"plain_text":"Before kitchen design / appliance procurement","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Bottled fixtures will need re-replacement → wasted cost; gas inspection may fail.","link":null},"plain_text":"Bottled fixtures will need re-replacement → wasted cost; gas inspection may fail.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/nw12344/20240104/fb733357d63c49e7b460f78ab6b27b13.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai renovation detailssubstitutionrenovation details (2024-01-04 renovation details renovation details)","link":null},"plain_text":"Shanghai renovation detailssubstitutionrenovation details (2024-01-04 renovation details renovation details)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Required record: the kitchen design''s gas-source assumption matches the community''s current/scheduled gas-supply mode.","link":null},"plain_text":"Required record: the kitchen design''s gas-source assumption matches the community''s current/scheduled gas-supply mode.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_aef07b615b2d', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_aef07b615b2d","link":null},"plain_text":"rule_aef07b615b2d","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_commercial_fit_out"}},"topic":{"type":"select","select":{"name":"commercial_fire_electric"}},"authority_level":{"type":"select","select":{"name":"industry_standard"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Commercial fit-out in Shanghai must meet: office-area strong+weak power load ≥4kW per 100㎡; fire-acceptance requirements (emergency lighting positions, evacuation-path width, smoke detectors); formaldehyde ≤0.05 mg/m³ (stricter than residential GB 0.10).","link":null},"plain_text":"Commercial fit-out in Shanghai must meet: office-area strong+weak power load ≥4kW per 100㎡; fire-acceptance requirements (emergency lighting positions, evacuation-path width, smoke detectors); formaldehyde ≤0.05 mg/m³ (stricter than residential GB 0.10).","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Validate the design''s power load + fire layout against these baselines before sealing; engage fire inspection coordinator; book formaldehyde retest before turnover.","link":null},"plain_text":"Validate the design''s power load + fire layout against these baselines before sealing; engage fire inspection coordinator; book formaldehyde retest before turnover.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Pre-seal review + pre-turnover retest","link":null},"plain_text":"Pre-seal review + pre-turnover retest","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Fire-acceptance failure → cannot occupy; tenants may withdraw; insurance void.","link":null},"plain_text":"Fire-acceptance failure → cannot occupy; tenants may withdraw; insurance void.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://hea.china.com/hea/xinwen/2025/1231/122025_1791228.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai renovation details renovation renovation details + renovation details acceptance inspection renovation details","link":null},"plain_text":"Shanghai renovation details renovation renovation details + renovation details acceptance inspection renovation details","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For commercial projects, verify the electrical load spec ≥4kW/100㎡ and the formaldehyde retest record ≤0.05 mg/m³ before turnover.","link":null},"plain_text":"For commercial projects, verify the electrical load spec ≥4kW/100㎡ and the formaldehyde retest record ≤0.05 mg/m³ before turnover.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_f51535bb6e72', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_f51535bb6e72","link":null},"plain_text":"rule_f51535bb6e72","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"shanghai_municipal"}},"topic":{"type":"select","select":{"name":"property_dispute"}},"authority_level":{"type":"select","select":{"name":"municipal_gov"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"From 2025-11-28, owners'' committees with active property-service bidding must use the new procurement procedure; property''s renovation-management duties (filing review, daily inspection, 24h escalation) must be explicit in the contract.","link":null},"plain_text":"From 2025-11-28, owners'' committees with active property-service bidding must use the new procurement procedure; property''s renovation-management duties (filing review, daily inspection, 24h escalation) must be explicit in the contract.","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Owners facing property disputes (deposit / pass / inspection) can reference the new contract terms when escalating; remote owners should mandate written response within 24h.","link":null},"plain_text":"Owners facing property disputes (deposit / pass / inspection) can reference the new contract terms when escalating; remote owners should mandate written response within 24h.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"At each property dispute or quarterly contract review","link":null},"plain_text":"At each property dispute or quarterly contract review","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Without contract anchor, disputes lack escalation footing.","link":null},"plain_text":"Without contract anchor, disputes lack escalation footing.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.shanghai.gov.cn/nw12344/20251128/8bbebad18f0d44b3945fc36c345c4701.html"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Shanghai property managementrenovation details (2025-11-28)","link":null},"plain_text":"Shanghai property managementrenovation details (2025-11-28)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_correspondence"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"For 2025-11-28 onward owner-property correspondence, verify the dispute reference cites the new procurement-procedure clause where applicable.","link":null},"plain_text":"For 2025-11-28 onward owner-property correspondence, verify the dispute reference cites the new procurement-procedure clause where applicable.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);
INSERT OR REPLACE INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('rule_c04ad49b5423', 'notion-db-property-rules', '{"rule_id":{"id":"title","type":"title","title":[{"type":"text","text":{"content":"rule_c04ad49b5423","link":null},"plain_text":"rule_c04ad49b5423","annotations":{},"href":null}]},"jurisdiction":{"type":"select","select":{"name":"national"}},"topic":{"type":"select","select":{"name":"warranty"}},"authority_level":{"type":"select","select":{"name":"national_ministry"}},"plain_language_rule":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Statutory warranty minima: general decoration ≥2 years; waterproofing (kitchen / bathroom / external wall) ≥5 years; water+electric concealed works — industry-standard ≥5 years; head-of-market firms commit 20 years (used as a benchmark; <10 years is a warning sign).","link":null},"plain_text":"Statutory warranty minima: general decoration ≥2 years; waterproofing (kitchen / bathroom / external wall) ≥5 years; water+electric concealed works — industry-standard ≥5 years; head-of-market firms commit 20 years (used as a benchmark; <10 years is a warning sign).","annotations":{},"href":null}]},"required_action":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Reject any contract whose warranty clauses fall below: 2 yr general / 5 yr waterproofing / 5 yr concealed water-electric; for old-house renovation, push for the 10-20 yr concealed-work warranty pattern.","link":null},"plain_text":"Reject any contract whose warranty clauses fall below: 2 yr general / 5 yr waterproofing / 5 yr concealed water-electric; for old-house renovation, push for the 10-20 yr concealed-work warranty pattern.","annotations":{},"href":null}]},"deadline_or_timing":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Pre-contract signing","link":null},"plain_text":"Pre-contract signing","annotations":{},"href":null}]},"penalty_or_risk":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Sub-minimum warranties unenforceable; later disputes lack contractual footing.","link":null},"plain_text":"Sub-minimum warranties unenforceable; later disputes lack contractual footing.","annotations":{},"href":null}]},"source_url":{"type":"url","url":"https://www.gov.cn/gongbao/content/2003/content_62197.htm"},"source_title":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"renovation detailsrenovationrenovation details renovation details renovation details (Art. 32)","link":null},"plain_text":"renovation detailsrenovationrenovation details renovation details renovation details (Art. 32)","annotations":{},"href":null}]},"evidence_register":{"type":"select","select":{"name":"project_knowledge_base"}},"project_control_note":{"type":"rich_text","rich_text":[{"type":"text","text":{"content":"Contract review trigger: any warranty clause below the statutory floor (2yr / 5yr / 5yr); for old-house projects, flag concealed-warranty <10 years.","link":null},"plain_text":"Contract review trigger: any warranty clause below the statutory floor (2yr / 5yr / 5yr); for old-house projects, flag concealed-warranty <10 years.","annotations":{},"href":null}]}}', '2026-06-01T09:00:00+08:00', '2026-06-01T09:00:00+08:00', 0);

